CREATE TABLE IF NOT EXISTS users (
 id uuid PRIMARY KEY, email text UNIQUE NOT NULL CHECK(email=lower(email)), verified_at timestamptz,
 status text NOT NULL DEFAULT 'onboarding' CHECK(status IN ('onboarding','review','active','suspended','deleted')),
 role text NOT NULL DEFAULT 'student' CHECK(role IN ('student','moderator','admin')),
 birth_date_private date, age_reviewed_at timestamptz, consent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS email_challenges(email text PRIMARY KEY, code_hash text NOT NULL, expires_at timestamptz NOT NULL, attempts integer NOT NULL DEFAULT 0, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits(key text PRIMARY KEY, count integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(user_id uuid PRIMARY KEY REFERENCES users(id),display_name text NOT NULL DEFAULT '',bio text NOT NULL DEFAULT '' CHECK(length(bio)<=300),department text NOT NULL DEFAULT '',year_level text NOT NULL DEFAULT '',interests text[] NOT NULL DEFAULT '{}',modes text[] NOT NULL DEFAULT '{}',paused boolean NOT NULL DEFAULT true,show_age boolean NOT NULL DEFAULT false,show_department boolean NOT NULL DEFAULT false,age_min integer NOT NULL DEFAULT 18 CHECK(age_min>=18),age_max integer NOT NULL DEFAULT 65 CHECK(age_max>=age_min AND age_max<=100),gender text NOT NULL DEFAULT '',preferred_genders text[] NOT NULL DEFAULT '{}',review_status text NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending','approved','rejected')),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS profile_photos(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),object_key text UNIQUE NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','uploaded','approved','rejected','delete_pending')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS swipes(actor_id uuid REFERENCES users(id),target_id uuid REFERENCES users(id),mode text NOT NULL CHECK(mode IN ('friends','dating','study')),decision text NOT NULL CHECK(decision IN ('like','pass')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,target_id,mode),CHECK(actor_id<>target_id));
CREATE TABLE IF NOT EXISTS matches(id uuid PRIMARY KEY,low_id uuid NOT NULL REFERENCES users(id),high_id uuid NOT NULL REFERENCES users(id),mode text NOT NULL,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(low_id,high_id,mode),CHECK(low_id<high_id));
CREATE TABLE IF NOT EXISTS conversations(id uuid PRIMARY KEY,match_id uuid UNIQUE REFERENCES matches(id),kind text NOT NULL DEFAULT 'direct',closed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversation_members(conversation_id uuid REFERENCES conversations(id),user_id uuid REFERENCES users(id),last_read_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(conversation_id,user_id));
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY,conversation_id uuid NOT NULL REFERENCES conversations(id),sender_id uuid NOT NULL REFERENCES users(id),client_nonce uuid NOT NULL,body text NOT NULL CHECK(length(body) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(conversation_id,sender_id,client_nonce));
CREATE INDEX IF NOT EXISTS messages_order ON messages(conversation_id,created_at,id);
CREATE TABLE IF NOT EXISTS blocks(blocker_id uuid REFERENCES users(id),blocked_id uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(blocker_id,blocked_id),CHECK(blocker_id<>blocked_id));
CREATE TABLE IF NOT EXISTS rooms(id uuid PRIMARY KEY,title text NOT NULL CHECK(length(title) BETWEEN 1 AND 80),topic text NOT NULL DEFAULT 'friends',kind text NOT NULL CHECK(kind IN ('public','private','quick','date')),host_id uuid REFERENCES users(id),capacity integer NOT NULL DEFAULT 4 CHECK(capacity BETWEEN 2 AND 6),status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS room_members(room_id uuid REFERENCES rooms(id),user_id uuid REFERENCES users(id),PRIMARY KEY(room_id,user_id));
CREATE TABLE IF NOT EXISTS room_bans(room_id uuid REFERENCES rooms(id),user_id uuid REFERENCES users(id),PRIMARY KEY(room_id,user_id));
ALTER TABLE conversations ADD COLUMN IF NOT EXISTS room_id uuid REFERENCES rooms(id);
CREATE TABLE IF NOT EXISTS room_tickets(id uuid PRIMARY KEY,room_id uuid NOT NULL REFERENCES rooms(id),user_id uuid NOT NULL REFERENCES users(id),session_id uuid NOT NULL REFERENCES sessions(id),token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE IF NOT EXISTS room_seats(room_id uuid REFERENCES rooms(id),user_id uuid REFERENCES users(id),connection_id uuid UNIQUE NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(room_id,user_id));
CREATE TABLE IF NOT EXISTS quick_queue(user_id uuid PRIMARY KEY REFERENCES users(id),mode text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS proposals(id uuid PRIMARY KEY,a_id uuid REFERENCES users(id),b_id uuid REFERENCES users(id),mode text NOT NULL,a_accepted boolean NOT NULL DEFAULT false,b_accepted boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'pending',room_id uuid REFERENCES rooms(id),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS call_invitations(id uuid PRIMARY KEY,sender_id uuid REFERENCES users(id),recipient_id uuid REFERENCES users(id),conversation_id uuid REFERENCES conversations(id),status text NOT NULL DEFAULT 'pending',room_id uuid REFERENCES rooms(id),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(sender_id<>recipient_id));
CREATE TABLE IF NOT EXISTS reports(id uuid PRIMARY KEY,reporter_id uuid REFERENCES users(id),subject_id uuid REFERENCES users(id),room_id uuid REFERENCES rooms(id),category text NOT NULL,description text NOT NULL DEFAULT '' CHECK(length(description)<=1000),status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events(id uuid PRIMARY KEY,actor_id uuid REFERENCES users(id),action text NOT NULL,target_id uuid,reason text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS campus_groups(id uuid PRIMARY KEY,title text NOT NULL,description text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS group_members(group_id uuid REFERENCES campus_groups(id),user_id uuid REFERENCES users(id),PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS posts(id uuid PRIMARY KEY,group_id uuid REFERENCES campus_groups(id),author_id uuid REFERENCES users(id),body text NOT NULL CHECK(length(body) BETWEEN 1 AND 2000),status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS events(id uuid PRIMARY KEY,title text NOT NULL,description text NOT NULL DEFAULT '',starts_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'approved');
